using NexaStation.Core;
using NexaStation.Domain;
using NexaStation.Media.Hub;

namespace NexaStation.Media.Associations;

public sealed class MediaAssociationService(IMediaPersistence persistence,ILibraryRepository library):IMediaAssociationService
{
    public async Task<MediaAssociation?> ResolveAsync(GalleryMediaItem item,CancellationToken cancellationToken=default){IReadOnlyList<MediaAssociation> all=await persistence.GetAssociationsAsync(cancellationToken);return all.Where(a=>Matches(a,item)).OrderByDescending(a=>Specificity(a.ScopeType)).ThenByDescending(a=>a.UpdatedAtUtc).FirstOrDefault();}
    public async Task<MediaLaunchPlan> CreateLaunchPlanAsync(GalleryMediaItem item,CancellationToken cancellationToken=default){MediaAssociation? association=await ResolveAsync(item,cancellationToken);if(association is null)return new(true,null,null,[item.FilePath],$"Open with Windows default: {item.FileName}");if(!IsSafeTemplate(association.ArgumentsTemplate))return new(false,null,null,[],"", "The preferred-player argument template is unsafe. Only {MEDIA_PATH} is permitted.");if(string.IsNullOrWhiteSpace(association.PlayerLibraryItemId))return new(true,null,null,[item.FilePath],$"Open with Windows default: {item.FileName}");LibraryItem? player=await library.GetByIdAsync(association.PlayerLibraryItemId,cancellationToken);LaunchTarget? target=player?.LaunchTargets.FirstOrDefault(value=>value.Id==association.LaunchTargetId&&value.IsEnabled)??player?.LaunchTarget;if(player is null||target is null||LaunchTargetValidator.Validate(target) is not null)return new(false,player,target,[],"","The preferred player or launch target is unavailable.");string template=string.IsNullOrWhiteSpace(association.ArgumentsTemplate)?"{MEDIA_PATH}":association.ArgumentsTemplate;string expanded=template.Replace("{MEDIA_PATH}",item.FilePath,StringComparison.Ordinal);return new(false,player,target,[expanded],$"{player.Title} {expanded}");}
    public Task SaveAsync(MediaAssociation association,CancellationToken cancellationToken=default){if(!IsSafeTemplate(association.ArgumentsTemplate))throw new ArgumentException("Only the {MEDIA_PATH} placeholder is allowed.",nameof(association));return persistence.SaveAssociationAsync(association,cancellationToken);}
    public static bool IsSafeTemplate(string? template){if(string.IsNullOrWhiteSpace(template))return true;string scrubbed=template.Replace("{MEDIA_PATH}",string.Empty,StringComparison.Ordinal);return !scrubbed.Contains('{')&&!scrubbed.Contains('}')&&!scrubbed.Contains("&&",StringComparison.Ordinal)&&!scrubbed.Contains("||",StringComparison.Ordinal)&&!scrubbed.Contains('>')&&!scrubbed.Contains('<')&&!scrubbed.Contains('|');}
    private static bool Matches(MediaAssociation a,GalleryMediaItem item)=>a.ScopeType switch{MediaAssociationScope.MediaItem=>string.Equals(a.ScopeValue,item.Id,StringComparison.Ordinal),MediaAssociationScope.GallerySource=>string.Equals(a.ScopeValue,item.GallerySourceId,StringComparison.Ordinal),MediaAssociationScope.FileExtension=>string.Equals(a.FileExtension??a.ScopeValue,item.Extension,StringComparison.OrdinalIgnoreCase),MediaAssociationScope.GlobalMediaType=>a.MediaType==item.MediaType,_=>false};
    private static int Specificity(MediaAssociationScope scope)=>scope switch{MediaAssociationScope.MediaItem=>4,MediaAssociationScope.GallerySource=>3,MediaAssociationScope.FileExtension=>2,_=>1};
}
